#include "stdlib/math/base/special/betainc.h"
#include "stdlib/math/base/special/kernel_betainc.h"
#include "stdlib/math/base/assert/is_probability.h"
#include "stdlib/math/base/assert/is_positive_finite.h"

/**
* Evaluates the incomplete beta function.
*
* @param {Probability} x - function parameter
* @param {NonNegativeNumber} a - function parameter
* @param {NonNegativeNumber} b - function parameter
* @param {boolean} [regularized=true] - boolean indicating if the function should evaluate the regularized or non-regularized incomplete beta function
* @param {boolean} [upper=false] - boolean indicating if the function should return the upper tail of the incomplete beta function
* @returns {number} function value
*
* @example
* var y = betainc( 0.5, 2.0, 2.0 );
* // returns 0.5
*
* @example
* var y = betainc( 0.5, 2.0, 2.0, false );
* // returns ~0.083
*
* @example
* var y = betainc( 0.2, 1.0, 2.0 );
* // returns 0.36
*/
void stdlib_base_betainc( double x, double a, double b, const bool regularized, const bool upper, double *out, double *derivative ) {
	if ( !stdlib_base_is_probability( x ) ) {
		// guard x [0, 1] ?
	}
	if ( !stdlib_base_is_positive_finite( a ) || !stdlib_base_is_positive_finite( b ) ) {
		// guard a, b >= 0	?
	}
	stdlib_base_kernel_betainc( x, a, b, regularized, upper, out, derivative );
}
